+// Regla de auditoría EMBA: todo motivo de anulación, ajuste o corrección tiene al menos 10 caracteres
+// (sin contar espacios de los bordes).
+export const MOTIVO_MIN_CARACTERES = 10;
+
+// RF-005, ADR-002: anula una factura emitida devolviendo una factura nueva; la original no se toca.
+// La anulada conserva el número original (supuesto 1 de la propuesta, pendiente de validar con el brain).
+export function anularFactura(factura, motivo) {
+  if (factura?.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  if (typeof motivo !== "string" || motivo.trim().length < MOTIVO_MIN_CARACTERES)
+    throw new Error(`El motivo de anulación debe tener al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+  const items = Object.freeze(factura.items.map((item) => Object.freeze({ ...item })));
+  return Object.freeze({ ...factura, items, estado: "anulada", motivo: motivo.trim() });
+}
